          { type: "match", q: "Match each research method to a disadvantage.", pairs: [["Postal survey", "Questions can't be clarified and may be ignored"], ["Observation", "Shows what happens but not why"], ["Focus group", "Expensive and time-consuming"], ["Government report", "May be out of date and too general"]] },
          { type: "type", q: "Research using data that has already been collected by others is called secondary or ______ research.", accept: ["desk"], explanation: "Desk research." }
